/* Original learning examples informed by the official references listed in README.md. */
window.APTITUDE_TOPICS = [
{id:'quantitative-aptitude',name:'Quantitative Aptitude',group:'Quantitative',filter:'quant',icon:'∑',tags:['percentages','ratios','arithmetic'],description:'Use arithmetic, ratios, percentages and estimation to solve practical and exam-style numerical problems.',overlap:'A broad umbrella that often includes Numerical Ability, Numerical Reasoning and Data Interpretation. The exact syllabus varies by exam.',source:'OpenStax Prealgebra 2e · ETS GRE Quantitative Reasoning',lessons:{Basic:['Translate words into operations: “of” usually means multiply; “remaining” often means subtract.','For a percent, convert p% to p/100 before multiplying. Estimate first to catch misplaced decimal points.','For ratios, add the parts to find the total number of equal shares, then scale each part.'],Intermediate:['Track successive percentage changes multiplicatively: a 20% increase then 20% decrease is 1.2 × 0.8, not zero change.','Compare two quantities by using a common base and consistent units.','When choices are far apart, estimation can eliminate answers before exact calculation.'],Advanced:['Represent constraints with variables, then test whether a result is exact or only an estimate.','Choose an efficient route: simplify fractions, factor, or use proportional reasoning before long arithmetic.','Check domain, units and plausibility; a percentage of a quantity cannot exceed it unless the rate exceeds 100%.']},quiz:[{q:'What is 15% of 200?',o:['15','30','45','170'],a:1,why:'15% = 15/100 = 0.15. Multiply 200 × 0.15 = 30.',wrong:['15 is the rate, not the calculated amount.','Correct: 200 × 15/100 = 30.','45 would be 22.5% of 200.','170 comes from subtracting 15% of 200 from 200; the question asks for the part.']},{q:'A price of 100 rises by 25% and then falls by 20%. What is the final price?',o:['95','100','105','120'],a:1,why:'After the rise: 100 × 1.25 = 125. Then 125 × 0.80 = 100. Apply each rate to its current base.',wrong:['The changes are not simply netted as a 5% decrease because their bases differ.','Correct: 125 × 0.8 = 100.','A 5% net increase would be 105, but sequential changes do not work that way.','This ignores the second decrease.']},{q:'A and B share 64 items in the ratio 3:5. How many does A receive?',o:['24','32','40','8'],a:0,why:'There are 3 + 5 = 8 equal parts. Each part is 64 ÷ 8 = 8, so A receives 3 × 8 = 24.',wrong:['Correct: 3 of 8 parts × 8 items per part = 24.','32 is half the total, not the 3-part share.','40 belongs to B, whose ratio part is 5.','8 is the size of one part, not A’s total.']} ]},
{id:'numerical-ability',name:'Numerical Ability',group:'Quantitative',filter:'quant',icon:'№',tags:['calculations','fractions','operations'],description:'Build accuracy with number sense, order of operations, fractions, decimals and everyday calculations.',overlap:'Usually focuses on calculation fluency; some tests use it interchangeably with numerical ability or basic quantitative aptitude.',source:'OpenStax Prealgebra 2e',lessons:{Basic:['Follow order of operations: parentheses, exponents, multiplication/division left to right, then addition/subtraction left to right.','Convert fractions, decimals and percentages when a form makes the calculation easier.','Estimate the size of an answer before calculating.'],Intermediate:['Use place value carefully when multiplying decimals; estimate the decimal position before placing it.','Simplify fractions by dividing numerator and denominator by the same nonzero factor.','Use inverse operations to check a result.'],Advanced:['Look for factors that cancel before multiplying large values.','For repeated calculations, preserve exact fractions until the final step to avoid rounding drift.','Check whether the question asks for an exact value, rounded value, or remainder.']},quiz:[{q:'Evaluate 36 ÷ 6 + 4.',o:['3','10','12','18'],a:1,why:'Division comes before addition: 36 ÷ 6 = 6, then 6 + 4 = 10.',wrong:['This treats the expression as 36 ÷ (6 + 4), but there are no parentheses.','Correct: perform division first, then addition.','This adds 6 + 4 incorrectly or changes the operation order.','This adds 36 and 6 before dividing, which changes the expression.']},{q:'What is 2.4 × 1.5?',o:['0.36','3.6','36','3.9'],a:1,why:'Compute 24 × 15 = 360. There are two decimal places in total, so 3.60 = 3.6.',wrong:['This places the decimal two places too far left.','Correct: 2.4 × 1.5 = 3.6.','This forgets to place the decimal point.','This adds the numbers instead of multiplying.']},{q:'What is 40% of 180, plus 15?',o:['72','87','87.5','195'],a:1,why:'40% of 180 = 0.4 × 180 = 72; 72 + 15 = 87.',wrong:['This is only 40% of 180 and omits the final +15.','Correct: 72 + 15 = 87.','This introduces an unsupported extra 0.5.','This adds 15 to 180 rather than to 40% of 180.']} ]},
{id:'logical-reasoning',name:'Logical Reasoning',group:'Reasoning',filter:'reasoning',icon:'∴',tags:['deduction','conditions','logic'],description:'Derive conclusions from stated rules, distinguish what must be true from what might be true, and avoid unsupported assumptions.',overlap:'A broad family that includes parts of analytical, verbal and general reasoning tests.',source:'OpenStax Contemporary Mathematics · Logical Arguments',lessons:{Basic:['Treat each premise as true for the question, even if it is unfamiliar.','In a chain “A are B; B are C,” it follows that A are C. The reverse does not automatically follow.','A conclusion is valid only when the premises guarantee it.'],Intermediate:['For if-then rules, separate the condition from the result. “If P then Q” does not imply “if Q then P.”','Use a small diagram or truth table when several conditions interact.','Look for counterexamples: one possible case can disprove a claim that says “always.”'],Advanced:['Translate negations carefully: “not (P and Q)” differs from “not P and not Q.”','Check argument form independently from whether a conclusion sounds plausible.','For multiple rules, chain only valid implications and preserve direction.']},quiz:[{q:'All roses are flowers. All flowers are plants. What must be true?',o:['All plants are roses.','All roses are plants.','Some plants are not flowers.','All flowers are roses.'],a:1,why:'Every rose belongs to the flowers group, and every flower belongs to the plants group. Therefore every rose is a plant.',wrong:['This reverses the relationship; the premises do not say every plant is a rose.','Correct: the two “all” relationships form a valid chain.','The premises do not establish whether such plants exist.','This reverses the first statement.']},{q:'If a device is charging, its indicator is lit. The indicator is not lit. What follows?',o:['The device is charging.','The device is not charging.','The indicator is broken.','Nothing can be concluded.'],a:1,why:'The rule says charging implies lit. Its contrapositive is: not lit implies not charging.',wrong:['This conflicts with the stated implication and observation.','Correct: the contrapositive is logically equivalent to the original rule.','Possible, but not stated or required.','A valid conclusion follows by contrapositive.']},{q:'Every member of Team X completed safety training. Rina is on Team X. Which conclusion follows?',o:['Rina completed safety training.','Rina leads Team X.','Everyone trained is on Team X.','Rina trained every team member.'],a:0,why:'Rina is a member of Team X, and every member of that team completed training. So Rina did too.',wrong:['Correct: apply the universal rule to Rina.','Leadership is not mentioned.','This reverses “every member is trained”; trained people may be outside Team X.','The rule says members completed training, not who trained them.']} ]},
{id:'analytical-reasoning',name:'Analytical Reasoning',group:'Reasoning',filter:'reasoning',icon:'⌘',tags:['ordering','constraints','cases'],description:'Organize several conditions into a model, test cases systematically and identify which arrangements satisfy every rule.',overlap:'Often appears as analytical reasoning, puzzle reasoning or games; specific formats vary among exams.',source:'OpenStax Contemporary Mathematics · Logical Arguments',lessons:{Basic:['List each item and each constraint before trying arrangements.','Convert “before,” “after,” “next to” and “not with” into clear relationships.','Reject a case as soon as it violates one rule.'],Intermediate:['Draw a sequence, table or grouping diagram that matches the problem.','Place the most restrictive item first; it usually reduces the number of cases.','Keep separate scenarios when a rule creates two possible branches.'],Advanced:['Use deductions to eliminate impossible branches before checking every permutation.','Track which statements are necessary and which are merely sufficient.','Verify the final arrangement against every original condition, not just the last clue.']},quiz:[{q:'Ava presents before Ben. Ben presents before Cara. What is the order?',o:['Ava, Ben, Cara','Ben, Ava, Cara','Cara, Ben, Ava','Ava, Cara, Ben'],a:0,why:'The constraints give Ava < Ben and Ben < Cara; combining them yields Ava < Ben < Cara.',wrong:['Correct: this satisfies both precedence rules.','Ava must be before Ben, so this fails.','This reverses both constraints.','Ben must be before Cara, so this fails.']},{q:'Four talks W, X, Y, Z are in a row. W is first and Z is last. X is immediately before Y. Where are X and Y?',o:['2 and 3','3 and 4','1 and 2','4 and 3'],a:0,why:'W occupies position 1 and Z position 4. The only remaining consecutive positions are 2 and 3, so X=2 and Y=3.',wrong:['Correct: W remains first, and X is immediately before Y.','Position 4 is already occupied by Z.','Position 1 is occupied by W.','This places Y before X.']},{q:'A, B and C each take one distinct day Monday–Wednesday. A is before C, and B is not Monday. If C is Wednesday, who is Monday?',o:['A','B','C','Cannot determine'],a:0,why:'C is Wednesday, and A must be before C. B cannot be Monday. Therefore A must take Monday and B Tuesday.',wrong:['Correct: eliminating B and C leaves A on Monday.','B is explicitly not Monday.','C is fixed on Wednesday.','The constraints determine a unique Monday assignment.']} ]},
{id:'verbal-reasoning',name:'Verbal Reasoning',group:'Language',filter:'language',icon:'“ ”',tags:['inference','passages','evidence'],description:'Read statements or short passages and decide what is supported, contradicted or left uncertain by the words provided.',overlap:'Uses language as evidence for logic; it is distinct from grammar and vocabulary exercises in Verbal Ability.',source:'OpenStax Contemporary Mathematics · Logical Arguments',lessons:{Basic:['Answer from the passage rather than from personal knowledge.','“Some” means at least one; it does not mean most or all.','Separate a stated fact from a plausible guess.'],Intermediate:['Track quantifiers such as all, none, only, most and unless.','For inference questions, choose the strongest conclusion that does not add assumptions.','If a passage gives an example, do not treat it as a universal rule.'],Advanced:['Notice scope: “not all” means at least one exception, not “none.”','Compare the exact claim with the evidence; small wording changes can alter meaning.','Mark a conclusion “cannot say” when both it and its opposite remain possible.']},quiz:[{q:'Passage: “Some library visitors borrow e-books. Every e-book borrower has a library account.” What must be true?',o:['Every visitor borrows an e-book.','Some library visitors have a library account.','Every account holder borrows e-books.','No visitor borrows print books.'],a:1,why:'At least one visitor borrows an e-book, and every such borrower has an account. So at least one visitor has an account.',wrong:['“Some” does not mean every.','Correct: combine the existence of some borrowers with the account rule.','This reverses the implication.','Print-book borrowing is not discussed.']},{q:'“The café extended its opening hours in May. Its sales also rose in May.” Which conclusion is best supported?',o:['Longer hours caused the sales rise.','Sales rose after the hours changed, but cause is not established.','The café was open 24 hours.','Sales rose only because of longer hours.'],a:1,why:'The passage reports two events occurring in the same period. It gives timing, not evidence that one caused the other.',wrong:['Correlation in timing alone does not prove causation.','Correct: this states only what the information supports.','No exact opening schedule is provided.','“Only because” is an unsupported causal claim.']},{q:'Statement: “Not every applicant passed the assessment.” Which interpretation follows?',o:['No applicants passed.','At least one applicant did not pass.','Most applicants passed.','Every applicant failed.'],a:1,why:'“Not every” means the universal claim is false: at least one applicant is an exception.',wrong:['This says none passed, which is stronger.','Correct: at least one did not pass.','The proportion passing is unknown.','This also says none passed, which is unsupported.']} ]},
{id:'non-verbal-reasoning',name:'Non-Verbal Reasoning',group:'Reasoning',filter:'reasoning',icon:'◇',tags:['figures','visual patterns','rotation'],description:'Read visual relationships in shapes, positions, shading and transformations without relying on long text.',overlap:'Often shares pattern questions with Abstract and Spatial Ability; this track focuses on rule-finding across visual items.',source:'Original visual pattern exercises; see related logical pattern methods in OpenStax Contemporary Mathematics',lessons:{Basic:['Compare one feature at a time: count, shape, fill, direction or position.','Describe the transformation in words before choosing the next figure.','Check whether the rule changes every step or alternates.'],Intermediate:['Track two independent features, such as rotation plus a changing number of dots.','For alternating patterns, compare odd-position figures with each other and even-position figures.','Use elimination when an option violates even one feature rule.'],Advanced:['Represent a figure as a set of attributes and follow each attribute separately.','Test the proposed rule against every supplied transition, not only the first pair.','Distinguish a fixed rotation from reflection; they reverse orientation differently.']},quiz:[{q:'A figure gains one dot at each step: 1 dot, 2 dots, 3 dots. How many dots come next?',o:['2','3','4','5'],a:2,why:'The count increases by one each step: 1, 2, 3, so the next count is 4.',wrong:['The sequence already reached 3.','This repeats the previous figure instead of applying the rule.','Correct: add one dot.','This adds two without evidence.']},{q:'An arrow points ↑, then →, then ↓. If it turns 90° clockwise each time, what is next?',o:['↑','←','→','↓'],a:1,why:'A clockwise quarter-turn sequence continues ↑ → ↓ ←, so the next arrow points left.',wrong:['This is the starting direction after a full cycle, but the next step is left.','Correct: continue one 90° clockwise turn.','This is the second figure.','This is the third figure.']},{q:'A square is rotated 90° clockwise each move. A marked corner starts at the top-left. Where is it after two moves?',o:['Top-left','Top-right','Bottom-right','Bottom-left'],a:2,why:'After one clockwise turn the marked corner is top-right; after the second it is bottom-right.',wrong:['Two quarter-turns equal a half-turn.','This is the position after one turn.','Correct: the corner moves to the diagonally opposite location.','This is a counterclockwise result.']} ]},
{id:'abstract-reasoning',name:'Abstract Reasoning',group:'Reasoning',filter:'reasoning',icon:'◎',tags:['sequences','rules','patterns'],description:'Discover the underlying rule in unfamiliar symbols, numbers or shapes and apply it consistently.',overlap:'Can overlap with non-verbal reasoning; abstract reasoning emphasizes identifying a general rule rather than a specific school subject.',source:'OpenStax Contemporary Mathematics · Logical Arguments',lessons:{Basic:['Write down what changes between terms: add, subtract, rotate, alternate or repeat.','Check the simplest rule first, such as a constant difference.','Use the rule to predict one term, then verify it against earlier terms.'],Intermediate:['Compare first differences; if they change regularly, inspect second differences.','Test alternating subsequences when one simple rule does not fit every step.','Avoid a complicated rule if a simpler one explains all the data.'],Advanced:['Look for recursive rules, multiplicative growth, or combinations of two simple patterns.','For visual sequences, encode attributes such as count and orientation separately.','A valid pattern must explain every observed term; many sequences can fit a short list, so use the stated options and simplest consistent rule.']},quiz:[{q:'What comes next: 2, 6, 12, 20, 30, …?',o:['36','40','42','44'],a:2,why:'Differences are +4, +6, +8, +10. The next difference is +12, giving 30 + 12 = 42. Equivalently, terms are n(n+1).',wrong:['This adds only 6 to 30 and breaks the increasing even differences.','This adds 10 again rather than 12.','Correct: continue the difference pattern.','This adds 14 without a matching rule.']},{q:'What comes next: 3, 9, 27, …?',o:['30','54','81','729'],a:2,why:'Each term is multiplied by 3: 3 × 3 = 9, 9 × 3 = 27, so 27 × 3 = 81.',wrong:['This adds 3 instead of applying the repeated multiplication.','This doubles 27, but the ratio has been 3.','Correct: multiply 27 by 3.','This applies the rule twice in one step.']},{q:'A sequence alternates +2, then ×2: 3, 5, 10, 12, 24, … What comes next?',o:['26','36','48','50'],a:0,why:'The operations alternate. After ×2 from 12 to 24, apply +2: 26.',wrong:['Correct: the next operation in the alternating rule is +2.','This adds 12 and does not follow the operation pattern.','This multiplies by 2 again, skipping the alternating addition.','This applies the wrong operation to 24.']} ]},
{id:'data-interpretation',name:'Data Interpretation (DI)',group:'Quantitative',filter:'quant',icon:'▥',tags:['tables','charts','percentages'],description:'Extract values from tables, charts and graphs, then compare, combine or calculate rates without confusing labels or units.',overlap:'Applies numerical skills to presented data; commonly included within Quantitative Aptitude.',source:'OpenStax Introductory Statistics · ETS GRE Quantitative Reasoning',lessons:{Basic:['Read the title, labels, units and time period before using a chart.','Locate the requested row and column; keep units attached to values.','For a difference, subtract. For a share, divide part by total.'],Intermediate:['Check whether a chart uses counts, percentages, rates or cumulative totals.','Calculate percentage change as (new − old) ÷ old × 100%.','Compare ratios with a common denominator before ranking groups.'],Advanced:['Combine data only when categories and time periods are comparable.','Account for scale breaks and dual axes; visual height can mislead.','State the calculation path and round only at the end unless instructions say otherwise.']},quiz:[{q:'A table shows books read: Ana 12, Bo 8, Chen 10. How many books did they read altogether?',o:['20','28','30','32'],a:2,why:'Add the three values: 12 + 8 + 10 = 30.',wrong:['This omits one or more values.','This is not the sum of all three entries.','Correct: 12 + 8 + 10 = 30.','This adds an unsupported extra 2.']},{q:'Visitors rise from 80 in week 1 to 100 in week 2. What is the percentage increase?',o:['20%','25%','80%','125%'],a:1,why:'Increase = 100 − 80 = 20. Divide by the original 80: 20/80 × 100% = 25%.',wrong:['20 is the absolute increase, not the percentage.','Correct: compare the increase to the original value.','This is the ratio 80/100 expressed as a percent.','This is the new value as a percentage of the old value, not the increase.']},{q:'A chart shows Plan A: 240 users and Plan B: 300 users. By what percent is B higher than A?',o:['20%','25%','60%','80%'],a:1,why:'The difference is 300 − 240 = 60. Relative to A: 60/240 = 0.25 = 25%.',wrong:['This divides the difference by B (60/300), not by the comparison base A.','Correct: use A as the base because B is compared with A.','60 is the absolute difference.','This is 240 as a percentage of 300.']} ]},
{id:'data-sufficiency',name:'Data Sufficiency',group:'Quantitative',filter:'quant',icon:'?',tags:['information','sufficiency','conditions'],description:'Decide whether given statements provide enough information to answer a question, without doing unnecessary calculations.',overlap:'A question format used in some exams; it tests reasoning about information rather than one specific math topic.',source:'ETS GRE Quantitative Reasoning · OpenStax Contemporary Mathematics',lessons:{Basic:['Solve the question using statement 1 alone; do not combine it with statement 2 yet.','Repeat using statement 2 alone.','Then test both together only if neither alone is sufficient.'],Intermediate:['A statement is sufficient when it forces one answer, even if it does not reveal every variable.','Try counterexamples: if two allowed cases give different answers, that statement is insufficient.','Do not assume unstated restrictions such as positive integers.'],Advanced:['For yes/no questions, sufficiency means the answer is definitely yes or definitely no.','Check all solutions permitted by equations, including negative or non-integer values unless restricted.','Avoid solving for more than the requested quantity; uniqueness of the target is what matters.']},quiz:[{q:'Is x > 0? (1) x² = 9. (2) x³ > 0. Which statement is sufficient alone?',o:['Statement 1 only','Statement 2 only','Each alone','Neither alone'],a:1,why:'From x² = 9, x could be 3 or −3, so statement 1 is insufficient. If x³ > 0, then x must be positive, so statement 2 alone is sufficient.',wrong:['Statement 1 permits both positive and negative x.','Correct: x³ has the same sign as x, so a positive cube means x > 0.','Statement 1 is not sufficient, though statement 2 is.','Statement 2 alone determines the answer.']},{q:'Is n even? (1) n is divisible by 4. (2) n is an integer. Which is sufficient alone?',o:['Statement 1 only','Statement 2 only','Each alone','Neither alone'],a:0,why:'A number divisible by 4 is necessarily even, so statement 1 is sufficient. “n is an integer” alone allows odd and even values.',wrong:['Correct: every integer divisible by 4 is even.','Integers can be odd or even.','Statement 2 alone does not settle the answer.','Statement 1 is sufficient.']},{q:'What is the value of y? (1) y + z = 10. (2) z = 4. Which statements together are sufficient?',o:['Statement 1 alone','Statement 2 alone','Both together','Even both are insufficient'],a:2,why:'Statement 1 alone has two unknowns; statement 2 alone gives only z. Together, y + 4 = 10, so y = 6.',wrong:['Many pairs satisfy y + z = 10.','This gives z but not y.','Correct: substitute z = 4 to determine y uniquely.','Together they determine y.']} ]},
{id:'verbal-ability',name:'Verbal Ability',group:'Language',filter:'language',icon:'Aa',tags:['usage','vocabulary','sentence structure'],description:'Improve clarity in vocabulary, sentence structure, grammar and short-form comprehension.',overlap:'A general language-use area. English Language Ability is its English-specific track; other language modules need language-specific content.',source:'Original exercises; logic concepts cross-referenced with OpenStax Contemporary Mathematics',lessons:{Basic:['Read the whole sentence before choosing a word; meaning comes from context.','Make subject and verb agree in number.','Use punctuation to separate complete thoughts, not to join fragments randomly.'],Intermediate:['Prefer precise words over vague words when context provides a clear choice.','Keep verb tense consistent unless the timeline changes.','Remove redundant phrases while preserving the intended meaning.'],Advanced:['Check parallel structure in lists and comparisons.','Distinguish a modifier’s intended target from the nearest noun; rewrite ambiguous sentences.','For inference, select only what the passage supports, not what is merely likely.']},quiz:[{q:'Choose the sentence with correct subject–verb agreement.',o:['The list of items are on the desk.','The list of items is on the desk.','The lists of item is on the desk.','The list are on the desk.'],a:1,why:'The subject is singular “list.” The phrase “of items” modifies list but does not change its number, so use “is.”',wrong:['The verb incorrectly agrees with the nearby plural “items.”','Correct: singular subject “list” takes “is.”','Both number agreement and phrasing are incorrect.','The singular subject needs “is.”']},{q:'Choose the clearest concise sentence.',o:['Due to the fact that it rained, the match was postponed.','Because it rained, the match was postponed.','The match, which was a match, was postponed because of rain.','Rain was the reason why the match got postponed due to rain.'],a:1,why:'“Because” expresses the cause directly and removes unnecessary wording.',wrong:['This is grammatical but wordier than needed.','Correct: concise and clear.','This repeats “match.”','This repeats the cause and uses redundant phrasing.']},{q:'Choose the sentence with parallel structure.',o:['She enjoys reading, to hike, and cycling.','She enjoys reading, hiking, and cycling.','She enjoys to read, hiking, and to cycle.','She enjoys reading, hike, and to cycle.'],a:1,why:'All three activities use the same -ing form, making the list parallel.',wrong:['The forms do not match.','Correct: each item is a gerund.','The infinitive and gerund forms are mixed.','The forms are inconsistent.']} ]},
{id:'english-language-ability',name:'English Language Ability',group:'Language',filter:'language',icon:'En',tags:['English grammar','vocabulary','comprehension'],description:'Practise English grammar, vocabulary, reading comprehension and usage with clear examples and a staged path.',overlap:'This is the English-specific language track; use Language Learning to select another target language. It overlaps with Verbal Ability.',source:'Original English exercises; OpenStax Contemporary Mathematics for argument and inference concepts',lessons:{Basic:['Use the simple present for habits and general facts; use the simple past for finished past events.','Learn words in context with a sample sentence, not as isolated translations alone.','In a short passage, identify the main idea before answering detail questions.'],Intermediate:['Use present perfect for a past action connected to now; use simple past when a finished time is stated.','Notice collocations (words that naturally occur together) while reading.','Support comprehension answers with a phrase or fact from the text.'],Advanced:['Use conditionals to express real possibilities, hypothetical situations and counterfactual pasts accurately.','Distinguish tone, implication and explicit meaning in a passage.','Edit for cohesion: pronouns, transitions and tense should help the reader follow the same idea.']},quiz:[{q:'Choose the correct sentence about a finished event yesterday.',o:['I go to the office yesterday.','I went to the office yesterday.','I have gone to the office yesterday.','I going to the office yesterday.'],a:1,why:'“Yesterday” marks a finished past time, so use the simple past form “went.”',wrong:['The simple present conflicts with the finished past time.','Correct: “went” is the simple past of “go.”','Present perfect is generally not used with a specific finished time such as yesterday.','This sentence is missing an auxiliary and correct verb form.']},{q:'Complete: “She ___ here since 2022.”',o:['lives','lived','has lived','is live'],a:2,why:'“Since 2022” connects a situation that began in the past and continues now; present perfect “has lived” fits.',wrong:['Simple present does not express the stated duration as naturally in this structure.','Simple past suggests the living ended.','Correct: present perfect + since marks a continuing period.','This is not a grammatical verb form.']},{q:'“Although the route was longer, it was less crowded.” What contrast is expressed?',o:['The longer route had fewer people.','The route was closed.','The route was faster.','The speaker did not travel.'],a:0,why:'“Although” introduces a contrast: despite being longer, the route had the advantage of less crowding.',wrong:['Correct: this captures the contrast stated.','Closure is not mentioned.','Speed is not stated.','The sentence does not say whether the speaker travelled.']} ]},
{id:'qualitative-aptitude',name:'Qualitative Aptitude',group:'Applied skills',filter:'applied',icon:'◈',tags:['classification','attributes','careful reading'],description:'A guided set of attribute and classification exercises. The phrase “Qualitative Aptitude” is not one universally standardized exam section, so this app defines its scope clearly.',overlap:'Unlike common sections such as Quantitative Aptitude, this label is used inconsistently. Here it means reasoning about qualities, categories and stated attributes—not subjective judgments about people.',source:'Scope note: app-defined learning track; classification items are original',lessons:{Basic:['Identify the exact property named in the question, such as material, shape or function.','Classify only with evidence given in the prompt.','Do not confuse a familiar association with a guaranteed fact.'],Intermediate:['When several attributes are listed, separate necessary features from incidental details.','Compare items using the same criterion for every item.','If the information does not determine a classification, say so rather than guessing.'],Advanced:['Evaluate a classification rule against all examples, including edge cases.','Distinguish descriptive categories from value judgments.','Explain which stated attribute supports the category and why alternatives do not.']},quiz:[{q:'In a set, three objects are described as “made of metal”; one is described as “made of wood.” Which property separates the odd item?',o:['Size','Material','Color','Use'],a:1,why:'The only stated difference is material: three are metal and one is wood.',wrong:['No sizes are provided.','Correct: material is the attribute that differs.','No colors are provided.','No uses are provided.']},{q:'A classification rule says “items with four equal sides are squares.” Which assessment is accurate?',o:['The rule is sufficient to identify squares.','The rule may include shapes that are not squares.','The rule classifies every circle as a square.','The rule is about color.'],a:1,why:'Four equal sides alone could describe a rhombus with non-right angles. A square also requires four right angles.',wrong:['The condition is not sufficient; it omits angle information.','Correct: the rule can over-include rhombi.','No circle can meet the four-side condition.','Color is not involved.']},{q:'A report says a product is “lightweight, recyclable, and waterproof.” Which conclusion is supported?',o:['It is made of aluminum.','It has the three stated properties.','It is the best product.','It is inexpensive.'],a:1,why:'Only the three attributes are stated. Material, quality ranking and price cannot be inferred.',wrong:['Material is not specified.','Correct: this repeats the supported information without adding assumptions.','“Best” is a value judgment with no comparison criteria.','Price is not given.']} ]},
{id:'mental-ability',name:'Mental Ability',group:'Reasoning',filter:'reasoning',icon:'✧',tags:['observation','number sense','logic'],description:'Combine quick calculation, attention to detail, memory of rules and everyday logical observation.',overlap:'A broad label that can include numerical, logical and observational questions; exact coverage depends on the assessment.',source:'OpenStax Prealgebra 2e · OpenStax Contemporary Mathematics',lessons:{Basic:['Read carefully and underline the quantity or condition being asked about.','Use small, reliable mental steps instead of rushing.','Estimate first, then verify with an inverse operation.'],Intermediate:['Break multi-step problems into chunks and keep units visible.','Use divisibility, place value and simple patterns to reduce calculation.','For observation questions, compare one feature at a time.'],Advanced:['Choose a mental shortcut only when its conditions hold; verify the result another way.','Hold intermediate results carefully and avoid rounding too early.','Separate relevant details from distracting information in word problems.']},quiz:[{q:'What is 25% of 80?',o:['15','20','25','40'],a:1,why:'25% is one quarter. 80 ÷ 4 = 20.',wrong:['This is 18.75% of 80.','Correct: one quarter of 80 is 20.','This confuses the percent number with the result.','This is half of 80.']},{q:'A number is divisible by 2 and by 3. Which number could it be?',o:['14','18','25','27'],a:1,why:'A number divisible by 2 is even; divisible by 3 means its digit sum is a multiple of 3. 18 meets both tests.',wrong:['14 is even but 1 + 4 = 5 is not divisible by 3.','Correct: 18 is even and 1 + 8 = 9 is divisible by 3.','25 is not divisible by 2 or 3.','27 is divisible by 3 but is odd.']},{q:'A clock shows 3:00. What is the smaller angle between its hands?',o:['0°','45°','90°','180°'],a:2,why:'At 3:00 the minute hand points to 12 and the hour hand to 3. Each hour mark is 30°, so the angle is 3 × 30° = 90°.',wrong:['The hands point in different directions.','This is not the separation at 3:00.','Correct: three hour marks × 30° = 90°.','This is a straight angle, not the clock’s position.']} ]},
{id:'critical-thinking',name:'Critical Thinking',group:'Reasoning',filter:'reasoning',icon:'◉',tags:['evidence','claims','bias'],description:'Evaluate claims, evidence, assumptions and alternative explanations before deciding what a conclusion really shows.',overlap:'Supports verbal and analytical reasoning, but focuses on the quality of evidence and argument.',source:'OpenStax Contemporary Mathematics · Logical Arguments',lessons:{Basic:['Separate a claim from the evidence offered for it.','Ask whether the evidence directly supports the conclusion.','Anecdotes can illustrate but do not by themselves establish a general rule.'],Intermediate:['Check sample size, comparison groups and whether measurements are relevant.','Consider another explanation that could produce the same observation.','Distinguish correlation from causation and identify missing information.'],Advanced:['Look for hidden assumptions, selective evidence and wording that overstates certainty.','Ask what evidence would change your view; a strong claim should be testable.','Calibrate conclusions to evidence: “may suggest” is different from “proves.”']},quiz:[{q:'A school notices students who read more tend to have higher scores. What is the strongest conclusion from this observation alone?',o:['Reading more causes higher scores.','Higher scores cause more reading.','The two are associated; cause is not established.','Reading has no relationship to scores.'],a:2,why:'An association alone cannot establish direction or exclude other factors, such as prior skill or access to books.',wrong:['This asserts causation without ruling out alternatives.','Reverse causation is also possible but not established.','Correct: association is supported, causal direction is not.','The observation does show an association, so “no relationship” overstates.']},{q:'A company tests a new app with 8 volunteers who already like technology. What is the main concern?',o:['The sample may not represent typical users.','The app must be effective.','Eight is always enough.','Volunteers cannot provide feedback.'],a:0,why:'A small, self-selected group of technology enthusiasts may differ from the broader user population.',wrong:['Correct: selection and sample size limit generalization.','Positive interest does not prove effectiveness.','No universal sample-size rule makes eight always enough.','Volunteers can provide feedback, though the sample may be biased.']},{q:'A headline says “New study proves the snack boosts memory,” but the study only found a small association. What is the best critique?',o:['The headline overstates what association can establish.','The study is certainly fabricated.','The snack must harm memory.','Association always proves cause.'],a:0,why:'A small association does not by itself prove a causal effect; the headline’s “proves” is stronger than the evidence.',wrong:['Correct: the claim should match the evidence strength.','No information supports fabrication.','The evidence does not show harm.','Association alone is not proof of causation.']} ]},
{id:'problem-solving',name:'Problem Solving Ability',group:'Reasoning',filter:'reasoning',icon:'⌕',tags:['strategies','constraints','checking'],description:'Define a problem, choose a workable strategy, carry it out and verify that the solution meets the constraints.',overlap:'Uses quantitative and logical skills in practical contexts; questions may have more than one valid strategy.',source:'OpenStax Prealgebra 2e · OpenStax Contemporary Mathematics',lessons:{Basic:['Restate the goal and list known information.','Choose a representation: equation, sketch, table or ordered steps.','Check whether the answer solves the original question.'],Intermediate:['Break a complex task into smaller subproblems with clear dependencies.','Try a simpler case or work backward when forward steps are unclear.','Track constraints so a locally valid step does not break the whole plan.'],Advanced:['Compare strategies by time, cost, risk and reliability when more than one solution exists.','Test edge cases and identify assumptions that could make a solution fail.','Explain why the chosen method works, not just what answer it produced.']},quiz:[{q:'A class needs 24 chairs. Each row holds 6 chairs. How many full rows are needed?',o:['3','4','6','18'],a:1,why:'Divide the total chairs by capacity per row: 24 ÷ 6 = 4 rows.',wrong:['Three rows hold only 18 chairs.','Correct: 4 × 6 = 24.','Six rows would hold 36 chairs.','This subtracts rather than divides.']},{q:'A team has 3 hours to review 6 equal sections. What is the maximum time per section if all sections get equal time?',o:['20 minutes','30 minutes','36 minutes','60 minutes'],a:1,why:'Three hours is 180 minutes. 180 ÷ 6 = 30 minutes per section.',wrong:['This allocates only 2 hours total.','Correct: 30 × 6 = 180 minutes.','This allocates 216 minutes total.','This allocates 6 hours total.']},{q:'A route is 12 km each way. A person has already travelled 7 km toward the destination. How far remains to the destination and back home by the same route?',o:['5 km','12 km','17 km','24 km'],a:2,why:'5 km remains to the destination (12 − 7), then 12 km to return home: 5 + 12 = 17 km.',wrong:['This counts only the remaining outward distance.','This counts a full one-way trip from the start, not from the current position.','Correct: 5 km onward + 12 km home.','This counts a full round trip as if no distance had been travelled.']} ]},
{id:'decision-making',name:'Decision Making Ability',group:'Applied skills',filter:'applied',icon:'◇',tags:['priorities','trade-offs','choices'],description:'Compare options against goals, evidence, constraints and likely consequences; explain why a choice fits the situation.',overlap:'Some exams use structured decision scenarios; this is not the same as a single universal personality test.',source:'Original decision scenarios; OPM Situational Judgment Tests',lessons:{Basic:['Identify the goal and any non-negotiable constraints.','Compare choices using the same criteria.','Prefer a reasoned response over the first appealing option.'],Intermediate:['Weigh benefits, costs, likelihood and reversibility.','Consider who is affected and what information is still missing.','Choose a practical next step when a perfect answer is unavailable.'],Advanced:['Separate urgent from important and make trade-offs explicit.','Consider second-order consequences and how you will review the result.','When stakes are high and information is incomplete, gather critical facts or consult the right person before committing.']},quiz:[{q:'You have one hour before a deadline. One task is urgent and blocks a teammate; another is optional and can wait. What is the best first action?',o:['Do the optional task because it is easier.','Address the blocking urgent task, then reassess remaining time.','Ignore both tasks.','Ask the teammate to finish your task without context.'],a:1,why:'The urgent task blocks another person and has a deadline. Prioritize it, communicate progress, then reassess.',wrong:['Ease alone does not match urgency or impact.','Correct: this addresses the immediate dependency and preserves reassessment.','This fails to meet responsibilities.','Delegation without context or agreement is not a sound decision.']},{q:'Two suppliers meet quality requirements. Supplier A is cheaper but has uncertain delivery; Supplier B costs slightly more and confirms the deadline. The deadline is critical. Which choice is better supported?',o:['Choose A only because it is cheaper.','Choose B because reliable delivery fits the critical constraint.','Choose randomly.','Cancel the project.'],a:1,why:'When the deadline is critical, delivery reliability is a key criterion. B better satisfies that stated constraint.',wrong:['This ignores the critical deadline risk.','Correct: the choice explicitly weighs the constraint.','Random choice does not use the available evidence.','Cancellation is not justified by these facts.']},{q:'A decision is reversible and low-cost, but more research would take a week. What is a sensible approach?',o:['Make a small, monitored trial and review the outcome.','Wait indefinitely for certainty.','Commit the whole budget immediately.','Avoid setting any success measure.'],a:0,why:'A limited, reversible trial creates useful evidence while containing downside; define a review point and success measure.',wrong:['Correct: test on a small scale and review.','Perfect certainty may be impossible and delay has a cost.','This is disproportionate for an untested choice.','Without a measure, the trial cannot inform the decision.']} ]},
{id:'spatial-ability',name:'Spatial Ability',group:'Reasoning',filter:'reasoning',icon:'↗',tags:['directions','rotation','visualization'],description:'Reason about direction, orientation, shape movement and how parts fit into a whole.',overlap:'Shares visual items with Non-Verbal Reasoning, but emphasizes mental transformation and spatial relationships.',source:'Original spatial reasoning exercises; related transformation logic in OpenStax Contemporary Mathematics',lessons:{Basic:['Set a consistent reference direction before tracing a route.','For rotations, track the object’s orientation relative to itself.','Sketching a quick diagram is a valid way to reduce working-memory load.'],Intermediate:['Use a compass rose or coordinate grid for multi-turn direction problems.','Distinguish rotating an object from moving it without rotation.','For reflections, identify the mirror line and which distances remain unchanged.'],Advanced:['Track coordinates and orientation separately through a sequence of transformations.','For cube or net questions, preserve which faces share edges and which are opposite.','Check the final view from the requested observer’s orientation.']},quiz:[{q:'You face north, turn right, then turn right again. Which direction do you face?',o:['North','East','South','West'],a:2,why:'A right turn from north faces east; a second right turn faces south.',wrong:['This would require a full rotation.','This is after one right turn.','Correct: two 90° right turns make 180°.','This is a left turn from north.']},{q:'A point at (2, 1) is reflected across the y-axis. What are its new coordinates?',o:['(2, −1)','(−2, 1)','(−1, 2)','(−2, −1)'],a:1,why:'Reflection across the y-axis reverses the x-coordinate and leaves y unchanged: (2,1) → (−2,1).',wrong:['This reflects across the x-axis.','Correct: negate x only.','This swaps coordinates and changes signs without that rule.','This changes both coordinates.']},{q:'A shape is rotated 180° about the origin. Where does point (3, −2) move?',o:['(−3, 2)','(3, 2)','(−3, −2)','(2, −3)'],a:0,why:'A half-turn maps (x,y) to (−x,−y), so (3,−2) becomes (−3,2).',wrong:['Correct: negate both coordinates.','This changes only y.','This changes only x.','This swaps coordinates.']} ]},
{id:'mechanical-ability',name:'Mechanical Ability',group:'Applied skills',filter:'applied',icon:'⚙',tags:['gears','levers','forces'],description:'Learn basic mechanical relationships such as gear direction, levers and mechanical advantage through conceptual examples.',overlap:'Appears mainly in some technical, trade or defence assessments; it is not a standard requirement in every aptitude test.',source:'OpenStax College Physics · Simple Machines',lessons:{Basic:['A simple machine changes the size or direction of a force; it does not create energy.','Two external gears in contact rotate in opposite directions.','For a lever in balance, compare force × distance from the pivot on each side.'],Intermediate:['Mechanical advantage compares output force with input force in an idealized model.','A longer effort arm can reduce the force needed, while increasing the distance over which it acts.','Real machines lose some energy to friction, so actual output is lower than ideal.'],Advanced:['Use torque = force × perpendicular lever arm for a simple rotational balance.','In a gear train, each mesh reverses direction; the speed ratio depends on tooth counts.','State ideal assumptions and distinguish force advantage from speed or distance trade-offs.']},quiz:[{q:'Two external gears mesh. Gear A turns clockwise. In which direction does Gear B turn?',o:['Clockwise','Counterclockwise','It does not turn','Direction cannot be known'],a:1,why:'At the contact point their teeth move together, so two directly meshing external gears rotate in opposite directions.',wrong:['This would make the teeth move against one another at the mesh.','Correct: each external gear mesh reverses rotation direction.','The meshing transfers rotation.','The direction relationship is determined.']},{q:'A balanced lever has 10 N applied 2 m from the pivot on one side. What force at 1 m balances it on the other side?',o:['5 N','10 N','20 N','40 N'],a:2,why:'Balance torques: 10 N × 2 m = F × 1 m, so F = 20 N.',wrong:['This torque is only 5 N·m.','This gives 10 N·m, below the 20 N·m input torque.','Correct: equal torque requires 20 N at the shorter arm.','This is twice the required force.']},{q:'In an ideal lever, the effort arm is 4 m and the load arm is 1 m. What is the ideal mechanical advantage?',o:['0.25','1','4','5'],a:2,why:'For an ideal lever, mechanical advantage = effort arm ÷ load arm = 4 ÷ 1 = 4.',wrong:['This inverts the arm ratio.','This would mean no force advantage.','Correct: a four-times-longer effort arm gives ideal MA 4.','Adding the arms is not the ratio.']} ]},
{id:'clerical-aptitude',name:'Clerical Aptitude',group:'Applied skills',filter:'applied',icon:'≡',tags:['accuracy','comparison','checking'],description:'Practise rapid but careful comparison, alphabetic or numeric filing, matching records and spotting transcription errors.',overlap:'Used in some clerical or administrative assessments; accuracy and speed are both important, and the expected convention should be stated.',source:'Original comparison exercises',lessons:{Basic:['Compare strings character by character from the start.','Keep similar characters (O/0, I/1, S/5) distinct.','Use a consistent left-to-right checking method.'],Intermediate:['For sorting, identify the required key and tie-break rule before ordering.','Check every field that the task says must match; one matching field is not enough.','Separate speed from accuracy during practice and improve both gradually.'],Advanced:['Use chunking to compare long identifiers, then verify the boundary characters.','For record review, define a checklist and mark completed fields to avoid omissions.','When many records are involved, use a systematic sort or filter rather than visual memory alone.']},quiz:[{q:'Are these codes identical? AB-1048 and AB-104B',o:['Yes','No, the last characters differ','No, the middle digits differ','Cannot compare'],a:1,why:'The first code ends in digit 8; the second ends in letter B. They are not identical.',wrong:['The final character differs.','Correct: 8 and B are distinct characters.','The middle digits are both 104.','Both strings can be compared directly.']},{q:'Sort these IDs alphabetically: K12, K2, J9.',o:['J9, K12, K2','J9, K2, K12','K12, K2, J9','K2, K12, J9'],a:0,why:'Compare the first letter: J sorts before K. Between K12 and K2, literal character order compares the second character: 1 comes before 2, so K12 precedes K2. The stated convention is character-by-character.',wrong:['Correct under the stated character-by-character convention.','This treats the numeric portion as a number (natural sort), a different convention.','J should sort before K.','J should sort before K.']},{q:'A form must match name and date. Record 1: Mira Sen, 04/08. Record 2: Mira Sen, 04/09. Do they match on both fields?',o:['Yes','No, the date differs','No, the name differs','Not enough information'],a:1,why:'The names match, but the dates differ (08 versus 09). Both fields are required to match.',wrong:['One required field differs.','Correct: the date field differs.','The name fields are identical.','The provided fields are sufficient for comparison.']} ]},
{id:'general-intelligence',name:'General Intelligence',group:'Reasoning',filter:'reasoning',icon:'✳',tags:['mixed reasoning','patterns','deduction'],description:'Work across mixed reasoning formats—patterns, classification, deduction and simple quantitative relationships.',overlap:'A broad label that commonly combines several reasoning abilities; exact question mix depends on the test.',source:'OpenStax Prealgebra 2e · OpenStax Contemporary Mathematics',lessons:{Basic:['Identify the question type before solving: pattern, relationship, classification or deduction.','Use only the information given and keep each step explicit.','Check the answer against the original wording.'],Intermediate:['Switch representations when stuck: a table, diagram or equation may reveal a rule.','Use elimination carefully and explain why each rejected choice fails.','Notice when a question asks what must be true rather than what could be true.'],Advanced:['Combine two kinds of evidence without allowing one to override a stated condition.','Check edge cases and reverse implications.','Prefer the simplest rule that fits all examples, while verifying every transition.']},quiz:[{q:'Complete the analogy: Bird is to nest as bee is to …',o:['Den','Hive','Web','Stable'],a:1,why:'A nest is a common home associated with a bird; a hive is the corresponding home associated with bees.',wrong:['A den is associated with some animals but not the intended relation here.','Correct: a hive is a bee colony’s home.','A web is made by spiders.','A stable houses horses.']},{q:'All P are Q. No Q are R. What follows about P and R?',o:['Some P are R.','No P are R.','All R are P.','Cannot determine any relation.'],a:1,why:'Every P is within Q, and Q has no overlap with R. Therefore P cannot overlap with R.',wrong:['This contradicts the no-overlap condition.','Correct: P is a subset of Q, which is disjoint from R.','No premise says R belongs to P.','A definite non-overlap conclusion follows.']},{q:'A sequence is 4, 7, 13, 25, … Each term after the first is double the previous term minus 1. What is next?',o:['39','47','49','50'],a:2,why:'Apply the stated rule: 25 × 2 − 1 = 49.',wrong:['This does not apply ×2 − 1 to 25.','This is not 50 − 1.','Correct: 25 × 2 − 1 = 49.','This doubles 25 but omits the −1.']} ]},
{id:'general-mental-ability',name:'General Mental Ability (GMA)',group:'Reasoning',filter:'reasoning',icon:'◌',tags:['general reasoning','logic','numeracy'],description:'A broad practice track for basic mental reasoning, including numeric patterns, logical rules and careful interpretation.',overlap:'GMA is an umbrella term rather than one fixed universal syllabus; topics and difficulty vary by assessment.',source:'OpenStax Prealgebra 2e · OpenStax Contemporary Mathematics',lessons:{Basic:['Read the instruction exactly; identify whether it asks for a number, inference or best choice.','Break a task into small steps and check arithmetic.','Do not add assumptions that are not stated.'],Intermediate:['Use a quick sketch or table to organize several conditions.','Estimate to spot arithmetic slips, then compute exactly.','Test whether a conclusion must follow in every case.'],Advanced:['Manage multi-step reasoning by writing intermediate results clearly.','Check whether conditions are sufficient and whether exceptions remain.','Explain the reasoning chain so another person can locate a faulty assumption.']},quiz:[{q:'What is the next even number after 18?',o:['19','20','21','22'],a:1,why:'Even numbers are divisible by 2. After 18, the next even integer is 20.',wrong:['19 is odd.','Correct: 20 is the next integer divisible by 2.','21 is odd.','22 is even but not the next one.']},{q:'If every registered participant receives a badge, and Sam is registered, what follows?',o:['Sam receives a badge.','Sam organizes the event.','Only Sam receives a badge.','Everyone with a badge is registered.'],a:0,why:'Apply the general rule to Sam, who is stated to be registered.',wrong:['Correct: the universal condition applies to Sam.','No organizer role is stated.','The rule applies to every registered participant, not only Sam.','The implication cannot be reversed from the information given.']},{q:'A number is increased by 10% and becomes 55. What was the original number?',o:['45','50','49.5','60.5'],a:1,why:'Let the original be x. Then 1.10x = 55, so x = 55 ÷ 1.10 = 50.',wrong:['A 10% increase on 45 is 49.5.','Correct: 10% of 50 is 5, giving 55.','This is 10% less than 55, but the increase was based on the original.','This applies the percentage in the wrong direction.']} ]},
{id:'numerical-reasoning',name:'Numerical Reasoning',group:'Quantitative',filter:'quant',icon:'↗',tags:['rates','comparisons','number data'],description:'Reason about numerical information in context: rates, proportions, change, estimates and comparisons.',overlap:'Overlaps with Numerical Ability and DI; it emphasizes interpreting what numbers mean in the scenario.',source:'OpenStax Prealgebra 2e · ETS GRE Quantitative Reasoning',lessons:{Basic:['Identify what each number measures and keep units beside it.','For “per” rates, divide the first quantity by the second with units in the result.','Check whether a comparison asks for a difference, ratio or percentage.'],Intermediate:['Convert rates to common units before comparing.','For percentage change, divide by the starting value, not the ending value.','Use proportional reasoning when the relationship scales linearly.'],Advanced:['Check whether a rate is average, instantaneous or cumulative in the context.','For weighted averages, account for each group’s size rather than averaging group rates blindly.','Assess whether the numerical conclusion is meaningful given rounding and sample size.']},quiz:[{q:'A car travels 150 km in 3 hours at a constant rate. What is its average speed?',o:['30 km/h','45 km/h','50 km/h','450 km/h'],a:2,why:'Average speed = distance ÷ time = 150 km ÷ 3 h = 50 km/h.',wrong:['This divides incorrectly.','This is not 150 ÷ 3.','Correct: 50 kilometres per hour.','This multiplies distance by time instead of dividing.']},{q:'A team completes 18 tasks in 6 days at a steady rate. How many tasks per day?',o:['2','3','6','108'],a:1,why:'Rate = tasks ÷ days = 18 ÷ 6 = 3 tasks per day.',wrong:['This would give 12 tasks in six days.','Correct: 3 × 6 = 18.','This confuses days with tasks per day.','This multiplies the quantities rather than calculating a per-day rate.']},{q:'A 240 km trip is 40% complete. How many kilometres remain?',o:['96 km','120 km','144 km','200 km'],a:2,why:'Completed distance is 0.40 × 240 = 96 km. Remaining is 240 − 96 = 144 km, or 60%.',wrong:['This is the completed distance, not the remaining distance.','This is half of the trip.','Correct: 60% of 240 = 144 km remains.','This subtracts 40 rather than 40% of 240.']} ]},
{id:'situational-judgement',name:'Situational Judgment / Situational Awareness',group:'Applied skills',filter:'applied',icon:'◎',tags:['work scenarios','response choices','context'],description:'Consider realistic scenarios, recognize relevant people and constraints, and select a constructive response that fits the stated context.',overlap:'Situational judgment tests are context-dependent. A good response depends on role, policy and safety; this practice is educational, not a universal answer key.',source:'U.S. Office of Personnel Management · Situational Judgment Tests',lessons:{Basic:['Identify the immediate issue and who is affected.','Choose a response that is respectful, relevant and within your responsibility.','Avoid escalating or ignoring a concern without first understanding it.'],Intermediate:['Gather key facts, communicate clearly and use the appropriate process.','Consider confidentiality, fairness and proportionality.','When you cannot resolve an issue yourself, seek help from the right person promptly.'],Advanced:['Balance urgency, policy, impact and uncertainty; explain the trade-off.','Use direct, private communication for routine misunderstandings when appropriate.','For safety, misconduct or serious risk, follow applicable reporting channels rather than promising secrecy.']},quiz:[{q:'A teammate seems confused about a shared task due tomorrow. What is the best first response?',o:['Privately ask what is unclear and agree on next steps.','Complain about them to the whole team.','Ignore it and hope it is finished.','Complete their work without telling them.'],a:0,why:'A respectful direct check-in clarifies the obstacle and supports timely coordination.',wrong:['Correct: address the issue constructively and agree on action.','Public blame is disproportionate and may harm collaboration.','Ignoring a deadline risk does not help the team.','Doing the work without communication hides the problem and can create confusion.']},{q:'A coworker asks you to share a confidential file they are not authorized to see. What is the best response?',o:['Send it because they asked.','Decline to share it and direct them to the authorized access process.','Post it in the team chat.','Promise to send it later from a personal account.'],a:1,why:'Respect access controls and point the coworker to the approved process. If uncertain, check with the file owner or appropriate administrator.',wrong:['A request does not grant authorization.','Correct: protect confidentiality and use the proper channel.','This expands the disclosure.','A personal account would bypass controls.']},{q:'You notice a potential immediate safety hazard at work. What should you do first?',o:['Follow the workplace safety procedure and alert the responsible person promptly.','Wait until the next routine meeting.','Assume someone else has reported it.','Post an unverified accusation online.'],a:0,why:'A possible immediate hazard needs prompt action through the applicable safety process. Keep people safe and report factual observations.',wrong:['Correct: follow the relevant procedure and notify the responsible person.','Delay may expose people to harm.','Assumption risks leaving the hazard unreported.','Public accusations do not replace a prompt, factual safety report.']} ]}
];
